27: namespace uWS {
28:     /* Safari 15.0 - 15.3 has a completely broken compression implementation (client_no_context_takeover not
29:      * properly implemented) - so we fully disable compression for this browser :-(
30:      * see https://github.com/uNetworking/uWebSockets/issues/1347 */
31:     inline bool hasBrokenCompression(std::string_view userAgent) {
32:         size_t posStart = userAgent.find(" Version/15.");
33:         if (posStart == std::string_view::npos) return false;
34:         posStart += 12;
35: 
36:         size_t posEnd = userAgent.find(' ', posStart);
37:         if (posEnd == std::string_view::npos) return false;
38: 
39:         unsigned int minorVersion = 0;
40:         auto result = std::from_chars(userAgent.data() + posStart, userAgent.data() + posEnd, minorVersion);
41:         if (result.ec != std::errc()) return false;
42:         if (result.ptr != userAgent.data() + posEnd) return false; // do not accept trailing chars
43:         if (minorVersion > 3) return false; // we target just Safari 15.0 - 15.3
44: 
45:         if (userAgent.find(" Safari/", posEnd) == std::string_view::npos) return false;
46: 
47:         return true;
48:     }
