163:     /* Publishes a message to all websocket contexts - conceptually as if publishing to the one single
164:      * TopicTree of this app (technically there are many TopicTrees, however the concept is that one
165:      * app has one conceptual Topic tree) */
166:     bool publish(std::string_view topic, std::string_view message, OpCode opCode, bool compress = false) {
167:         /* Anything big bypasses corking efforts */
168:         if (message.length() >= LoopData::CORK_BUFFER_SIZE) {
169:             return topicTree->publishBig(nullptr, topic, {message, opCode, compress}, [](Subscriber *s, TopicTreeBigMessage &message) {
170:                 auto *ws = (WebSocket<SSL, true, int> *) s->user;
171: 
172:                 /* Send will drain if needed */
173:                 ws->send(message.message, (OpCode)message.opCode, message.compress);
174:             });
175:         } else {
176:             return topicTree->publish(nullptr, topic, {std::string(message), opCode, compress});
177:         }
178:     }
