255:     template <typename UserData>
256:     struct WebSocketBehavior {
257:         /* Disabled compression by default - probably a bad default */
258:         CompressOptions compression = DISABLED;
259:         /* Maximum message size we can receive */
260:         unsigned int maxPayloadLength = 16 * 1024;
261:         /* 2 minutes timeout is good */
262:         unsigned short idleTimeout = 120;
263:         /* 64kb backpressure is probably good */
264:         unsigned int maxBackpressure = 64 * 1024;
265:         bool closeOnBackpressureLimit = false;
266:         /* This one depends on kernel timeouts and is a bad default */
267:         bool resetIdleTimeoutOnSend = false;
268:         /* A good default, esp. for newcomers */
269:         bool sendPingsAutomatically = true;
270:         /* Maximum socket lifetime in minutes before forced closure (defaults to disabled) */
271:         unsigned short maxLifetime = 0;
272:         MoveOnlyFunction<void(HttpResponse<SSL> *, HttpRequest *, struct us_socket_context_t *)> upgrade = nullptr;
273:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *)> open = nullptr;
274:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, std::string_view, OpCode)> message = nullptr;
275:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, std::string_view, OpCode)> dropped = nullptr;
276:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *)> drain = nullptr;
277:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, std::string_view)> ping = nullptr;
278:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, std::string_view)> pong = nullptr;
279:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, std::string_view, int, int)> subscription = nullptr;
280:         MoveOnlyFunction<void(WebSocket<SSL, true, UserData> *, int, std::string_view)> close = nullptr;
281:     };
