293:     template <typename UserData>
294:     TemplatedApp &&ws(std::string pattern, WebSocketBehavior<UserData> &&behavior) {
295:         /* Don't compile if alignment rules cannot be satisfied */
296:         static_assert(alignof(UserData) <= LIBUS_EXT_ALIGNMENT,
297:         "µWebSockets cannot satisfy UserData alignment requirements. You need to recompile µSockets with LIBUS_EXT_ALIGNMENT adjusted accordingly.");
298: 
299:         if (!httpContext) {
300:             return std::move(static_cast<TemplatedApp &&>(*this));
301:         }
302: 
303:         /* Terminate on misleading idleTimeout values */
304:         if (behavior.idleTimeout && behavior.idleTimeout < 8) {
305:             std::cerr << "Error: idleTimeout must be either 0 or greater than 8!" << std::endl;
306:             std::terminate();
307:         }
308: 
309:         /* Maximum idleTimeout is 16 minutes */
310:         if (behavior.idleTimeout > 240 * 4) {
311:             std::cerr << "Error: idleTimeout must not be greater than 960 seconds!" << std::endl;
312:             std::terminate();
313:         }
314: 
315:         /* Maximum maxLifetime is 4 hours */
316:         if (behavior.maxLifetime > 240) {
317:             std::cerr << "Error: maxLifetime must not be greater than 240 minutes!" << std::endl;
318:             std::terminate();
319:         }
320: 
321:         /* If we don't have a TopicTree yet, create one now */
322:         if (!topicTree) {
323: 
324:             bool needsUncork = false;
325:             topicTree = new TopicTree<TopicTreeMessage, TopicTreeBigMessage>([needsUncork](Subscriber *s, TopicTreeMessage &message, TopicTree<TopicTreeMessage, TopicTreeBigMessage>::IteratorFlags flags) mutable {
326:                 /* Subscriber's user is the socket */
327:                 /* Unfortunately we need to cast is to PerSocketData = int
328:                  * since many different WebSocketContexts use the same
329:                  * TopicTree now */
330:                 auto *ws = (WebSocket<SSL, true, int> *) s->user;
331: 
332:                 /* If this is the first message we try and cork */
333:                 if (flags & TopicTree<TopicTreeMessage, TopicTreeBigMessage>::IteratorFlags::FIRST) {
334:                     if (ws->canCork() && !ws->isCorked()) {
335:                         ((AsyncSocket<SSL> *)ws)->cork();
336:                         needsUncork = true;
337:                     }
338:                 }
339: 
340:                 /* If we ever overstep maxBackpresure, exit immediately */
341:                 if (WebSocket<SSL, true, int>::SendStatus::DROPPED == ws->send(message.message, (OpCode)message.opCode, message.compress)) {
342:                     if (needsUncork) {
343:                         ((AsyncSocket<SSL> *)ws)->uncork();
344:                         needsUncork = false;
345:                     }
346:                     /* Stop draining */
347:                     return true;
348:                 }
349: 
350:                 /* If this is the last message we uncork if we are corked */
351:                 if (flags & TopicTree<TopicTreeMessage, TopicTreeBigMessage>::IteratorFlags::LAST) {
352:                     /* We should not uncork in all cases? */
353:                     if (needsUncork) {
354:                         ((AsyncSocket<SSL> *)ws)->uncork();
355:                     }
356:                 }
357: 
358:                 /* Success */
359:                 return false;
360:             });
361: 
362:             /* And hook it up with the loop */
363:             /* We empty for both pre and post just to make sure */
364:             Loop::get()->addPostHandler(topicTree, [topicTree = topicTree](Loop */*loop*/) {
365:                 /* Commit pub/sub batches every loop iteration */
366:                 topicTree->drain();
367:             });
368: 
369:             Loop::get()->addPreHandler(topicTree, [topicTree = topicTree](Loop */*loop*/) {
370:                 /* Commit pub/sub batches every loop iteration */
371:                 topicTree->drain();
372:             });
373:         }
374: 
375:         /* Every route has its own websocket context with its own behavior and user data type */
376:         auto *webSocketContext = WebSocketContext<SSL, true, UserData>::create(Loop::get(), (us_socket_context_t *) httpContext, topicTree);
377: 
378:         /* We need to clear this later on */
379:         webSocketContextDeleters.push_back([webSocketContext]() {
380:             webSocketContext->free();
381:         });
382: 
383:         /* We also keep this list for easy closing */
384:         webSocketContexts.push_back((void *)webSocketContext);
385: 
386:         /* Quick fix to disable any compression if set */
387: #ifdef UWS_NO_ZLIB
388:         behavior.compression = DISABLED;
389: #endif
390: 
391:         /* If we are the first one to use compression, initialize it */
392:         if (behavior.compression) {
393:             LoopData *loopData = (LoopData *) us_loop_ext(us_socket_context_loop(SSL, webSocketContext->getSocketContext()));
394: 
395:             /* Initialize loop's deflate inflate streams */
396:             if (!loopData->zlibContext) {
397:                 loopData->zlibContext = new ZlibContext;
398:                 loopData->inflationStream = new InflationStream(CompressOptions::DEDICATED_DECOMPRESSOR);
399:                 loopData->deflationStream = new DeflationStream(CompressOptions::DEDICATED_COMPRESSOR);
400:             }
401:         }
402: 
403:         /* Copy all handlers */
404:         webSocketContext->getExt()->openHandler = std::move(behavior.open);
405:         webSocketContext->getExt()->messageHandler = std::move(behavior.message);
406:         webSocketContext->getExt()->droppedHandler = std::move(behavior.dropped);
407:         webSocketContext->getExt()->drainHandler = std::move(behavior.drain);
408:         webSocketContext->getExt()->subscriptionHandler = std::move(behavior.subscription);
409:         webSocketContext->getExt()->closeHandler = std::move(behavior.close);
410:         webSocketContext->getExt()->pingHandler = std::move(behavior.ping);
411:         webSocketContext->getExt()->pongHandler = std::move(behavior.pong);
412: 
413:         /* Copy settings */
414:         webSocketContext->getExt()->maxPayloadLength = behavior.maxPayloadLength;
415:         webSocketContext->getExt()->maxBackpressure = behavior.maxBackpressure;
416:         webSocketContext->getExt()->closeOnBackpressureLimit = behavior.closeOnBackpressureLimit;
417:         webSocketContext->getExt()->resetIdleTimeoutOnSend = behavior.resetIdleTimeoutOnSend;
418:         webSocketContext->getExt()->sendPingsAutomatically = behavior.sendPingsAutomatically;
419:         webSocketContext->getExt()->maxLifetime = behavior.maxLifetime;
420:         webSocketContext->getExt()->compression = behavior.compression;
421: 
422:         /* Calculate idleTimeoutCompnents */
423:         webSocketContext->getExt()->calculateIdleTimeoutCompnents(behavior.idleTimeout);
424: 
425:         httpContext->onHttp("GET", pattern, [webSocketContext, behavior = std::move(behavior)](auto *res, auto *req) mutable {
426: 
427:             /* If we have this header set, it's a websocket */
428:             std::string_view secWebSocketKey = req->getHeader("sec-websocket-key");
429:             if (secWebSocketKey.length() == 24) {
430: 
431:                 /* Emit upgrade handler */
