436:                         std::string_view secWebSocketExtensions = req->getHeader("sec-websocket-extensions");
437:                         memset((void *) secWebSocketExtensions.data(), ' ', secWebSocketExtensions.length());
438:                     }
439: 
440:                     behavior.upgrade(res, req, (struct us_socket_context_t *) webSocketContext);
441:                 } else {
442:                     /* Default handler upgrades to WebSocket */
443:                     std::string_view secWebSocketProtocol = req->getHeader("sec-websocket-protocol");
444:                     std::string_view secWebSocketExtensions = req->getHeader("sec-websocket-extensions");
445: 
446:                     /* Safari 15 hack */
447:                     if (hasBrokenCompression(req->getHeader("user-agent"))) {
448:                         secWebSocketExtensions = "";
449:                     }
450: 
451:                     res->template upgrade<UserData>({}, secWebSocketKey, secWebSocketProtocol, secWebSocketExtensions, (struct us_socket_context_t *) webSocketContext);
452:                 }
453: 
454:                 /* We are going to get uncorked by the Http get return */
455: 
456:                 /* We do not need to check for any close or shutdown here as we immediately return from get handler */
457: 
458:             } else {
459:                 /* Tell the router that we did not handle this request */
460:                 req->setYield(true);
461:             }
