    TemplatedApp &&preOpen(LIBUS_SOCKET_DESCRIPTOR (*handler)(struct us_socket_context_t *, LIBUS_SOCKET_DESCRIPTOR, char *, int)) {
        httpContext->onPreOpen(handler);
        return std::move(static_cast<TemplatedApp &&>(*this));
